// @flow
import '@fortawesome/fontawesome-free/css/all.css';
import '@fortawesome/fontawesome-free/css/v4-shims.css';
import './sulu-icon.css';
import React from 'react';
import classNames from 'classnames';
import log from 'loglevel';
import iconStyles from './icon.scss';
import type {ElementRef} from 'react';

type Props = {
    'aria-hidden'?: boolean,
    className?: string,
    iconRef?: (ref: ?ElementRef<'span'>) => void,
    name: string,
    onClick?: () => void,
    style?: Object,
};

function logInvalidIconWarning(name: string) {
    log.warn('Invalid icon given: "' + name + '"');
}

export default class Icon extends React.PureComponent<Props> {
    handleClick = (event: SyntheticEvent<HTMLElement>) => {
        const {onClick} = this.props;

        if (!onClick) {
            return;
        }

        event.stopPropagation();
        onClick();
    };

    handleKeypress = (event: SyntheticKeyboardEvent<HTMLElement>) => {
        const {onClick} = this.props;

        if (!onClick) {
            return;
        }

        if (event.key === 'Enter' || event.key === ' ') {
            event.stopPropagation();
            onClick();
        }
    };

    render() {
        const {className, name, onClick, iconRef, style} = this.props;
        const ariaHidden = this.props['aria-hidden'];
        let fontClass = '';

        if (!name || name.length <= 0) {
            logInvalidIconWarning(name);

            return null;
        }

        switch (name.substr(0, 3)) {
            case 'su-':
                fontClass = null;
                break;
            case 'fa-':
                fontClass = 'fa';
                break;
            case 'fas':
            case 'fab':
                fontClass = null;
                break;
            default:
                logInvalidIconWarning(name);

                return null;
        }

        const iconClass = classNames(
            fontClass ? fontClass : undefined,
            name,
            {
                [iconStyles.clickable]: onClick,
            },
            className
        );

        const onClickProperties = onClick
            ? {
                onClick: this.handleClick,
                onKeyPress: this.handleKeypress,
                role: 'button',
                tabIndex: 0,
            }
            : {};

        return (
            <span
                aria-hidden={ariaHidden ? true : undefined}
                aria-label={ariaHidden ? undefined : name}
                className={iconClass}
                ref={iconRef}
                style={style}
                {...onClickProperties}
            />
        );
    }
}
